mapper.sql:
r.tenant_id = #{query.tenantId} AND r.deleted = b'0' AND r.outcome = 'ABNORMAL'
AND r.create_time <= #{query.dataAsOf}

  AND t.project_id IN #{id}
AND 1 = 0
AND r.rule_revision_id = #{query.ruleRevisionId}
AND i.detection_id = #{query.detectionId}
AND v.category_code = #{query.categoryCode}
AND v.severity_code = #{query.severityCode}
AND d.product_model = #{query.productModel}
AND r.create_time >= #{query.fromAt}
AND r.create_time < #{query.toAt}

JOIN srv_inspection_annotation a ON a.tenant_id = r.tenant_id AND a.result_id = r.id AND a.deleted = b'0'
  AND a.kind = 'FALSE_POSITIVE' AND a.annotated_at <= #{query.dataAsOf}
LEFT JOIN srv_inspection_feedback_confirmation f ON f.tenant_id = a.tenant_id AND f.annotation_id = a.id
  AND f.deleted = b'0' AND f.confirmed_at <= #{query.dataAsOf}
  AND NOT EXISTS (SELECT 1 FROM srv_inspection_feedback_confirmation f2 WHERE f2.tenant_id = f.tenant_id
    AND f2.annotation_id = f.annotation_id AND f2.deleted = b'0' AND f2.revision_no > f.revision_no AND f2.confirmed_at <= #{query.dataAsOf})
